import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1961年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1961年/核心总结.md","filePath":"01_letters/1961年/核心总结.md"}'),n={name:"01_letters/1961年/核心总结.md"};function i(l,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1961年-核心总结" tabindex="-1">1961年 核心总结 <a class="header-anchor" href="#_1961年-核心总结" aria-label="Permalink to &quot;1961年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1961年是巴菲特合伙企业的大丰收之年。道琼斯指数全年上涨22.2%，而合伙企业回报率高达45.9%，几乎是市场的两倍。年末合伙企业净资产达到717万美元，合伙人数量超过90位，业务规模再创新高。巴菲特在信中对此表示满意，同时提醒合伙人保持理性——好年景不代表未来年年如此。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>本年度最重要的里程碑是首次控股登普斯特农机制造公司（Demster Farm Equipment）。这标志着巴菲特从单纯的二级市场投资开始向实业控股延伸。登普斯特是一家陷入困境的农机制造商，巴菲特通过购买其可转换债券和普通股获得控制权。这一转变对巴菲特的投资生涯意义深远：从此他不仅要分析股票，还要亲力亲为改善企业经营。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特在信中系统阐述了&quot;控股型投资&quot;的概念。当持股比例足以影响公司决策时，投资者的分析框架要从&quot;市场短期报价&quot;转向&quot;企业长期内在价值&quot;。他开始思考如何通过改善管理层、优化资本配置来提升控股公司的价值。这一思路为他后来收购伯克希尔·哈撒韦奠定了方法论基础。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>汤姆·纳普（Tom Knapp）是登普斯特原有的管理者，在公司最困难的时期发挥了一定作用。此外，随着合伙人数量突破90位，巴菲特的资产管理职责日益繁重，他开始在信中更加系统地向合伙人报告投资思路和业绩归因。</p>',9)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
